  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    allocations = [seg['minimum'] for seg in segments]
    remaining = budget - sum(allocations)
    if remaining < 0:
        raise ValueError('Budget below sum of minimums')
    cap_total = sum(seg['capacity'] for seg in segments)
    if remaining > cap_total - sum(allocations):
        raise ValueError('Budget exceeds total capacity')
    while remaining > 0:
        best_idx = -1
        best_val = -1.0
        for i, seg in enumerate(segments):
            if allocations[i] >= seg['capacity']:
                continue
            # importance divided by next allocated position
            val = seg['importance'] / (allocations[i] + 1)
            if val > best_val:
                best_val = val
                best_idx = i
        if best_idx == -1:
            break
        allocations[best_idx] += 1
        remaining -= 1
    total = sum(allocations)
    by_name = {segments[i]['name']: allocations[i] for i in range(n)}
    return {
        'allocations': allocations,
        'by_name': by_name,
        'total': total
    }
